using System;using System.IO;using System.Linq;using System.Collections.Generic;using Newtonsoft.Json.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using SpatialWallpaper.Sdk;using SpatialWallpaper.Sdk.Editor;
public static partial class WallpaperSceneBuilder {
 public const string Base="Assets/WallpaperSdkScenes";static string scene,folder;static int serial;
 static T Save<T>(T value,string name)where T:UnityEngine.Object {string path=folder+"/"+name;var previous=AssetDatabase.LoadAssetAtPath<T>(path);if(previous){EditorUtility.CopySerialized(value,previous);UnityEngine.Object.DestroyImmediate(value);return previous;}AssetDatabase.CreateAsset(value,path);return value;}
 static Material Material(string shader,string name){var found=Shader.Find(shader);if(!found)throw new InvalidDataException("scene-shader-missing:"+shader);return Save(new Material(found),name+".mat");}
 static Texture2D Texture(string name,int size=256,bool linear=false){string path=Base+"/Source/"+scene+"/"+name;var importer=AssetImporter.GetAtPath(path) as TextureImporter;if(!importer)throw new InvalidDataException("scene-texture-missing:"+path);importer.maxTextureSize=size;importer.sRGBTexture=!linear;importer.wrapMode=TextureWrapMode.Repeat;importer.mipmapEnabled=true;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 static AudioClip Music(){string path=Base+"/"+scene+"/Audio/Music.wav";var importer=AssetImporter.GetAtPath(path) as AudioImporter;if(!importer)throw new InvalidDataException("scene-music-missing:"+path);var settings=importer.defaultSampleSettings;settings.loadType=AudioClipLoadType.DecompressOnLoad;settings.compressionFormat=AudioCompressionFormat.PCM;importer.defaultSampleSettings=settings;importer.loadInBackground=false;importer.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<AudioClip>(path);}
 static MeshRenderer Mesh(Transform root,Mesh source,Matrix4x4 matrix,Material material,string name,int submesh=0){
  var p=source.vertices;var n=source.normals;var t=source.tangents;var uv=source.uv;var uv2=source.uv2;var colors=source.colors;var original=source.GetTriangles(submesh);if(scene=="RainyCafe"){var kept=new List<int>();for(int at=0;at<original.Length;at+=3){var center=matrix.MultiplyPoint3x4((p[original[at]]+p[original[at+1]]+p[original[at+2]])/3);if(CafeCoveredByDetail(name,center))continue;kept.Add(original[at]);kept.Add(original[at+1]);kept.Add(original[at+2]);}original=kept.ToArray();}var remap=new Dictionary<int,int>();var unique=new List<int>();bool baked=scene=="Train";var bakedVertices=new Dictionary<Tuple<Vector3,Vector2>,int>();var surfaceVertices=new Dictionary<Tuple<Vector3,Vector3,Vector4,Vector2,Vector2,Color>,int>();foreach(int index in original){if(remap.ContainsKey(index))continue;int mapped;if(baked){var key=Tuple.Create(p[index],uv.Length==p.Length?uv[index]:Vector2.zero);if(!bakedVertices.TryGetValue(key,out mapped)){mapped=unique.Count;unique.Add(index);bakedVertices.Add(key,mapped);}}else if(scene=="RainyCafe"){var key=Tuple.Create(p[index],n.Length==p.Length?n[index]:Vector3.up,t.Length==p.Length?t[index]:new Vector4(1,0,0,1),uv.Length==p.Length?uv[index]:Vector2.zero,uv2.Length==p.Length?uv2[index]:Vector2.zero,colors.Length==p.Length?colors[index]:Color.white);if(!surfaceVertices.TryGetValue(key,out mapped)){mapped=unique.Count;unique.Add(index);surfaceVertices.Add(key,mapped);}}else{mapped=unique.Count;unique.Add(index);}remap.Add(index,mapped);}var used=unique.ToArray();var normalMatrix=matrix.inverse.transpose;
  var mesh=new Mesh{name=name,indexFormat=IndexFormat.UInt32};mesh.vertices=used.Select(i=>matrix.MultiplyPoint3x4(p[i])).ToArray();if(baked)mesh.normals=Enumerable.Repeat(Vector3.up,used.Length).ToArray();else if(n.Length==p.Length)mesh.normals=used.Select(i=>normalMatrix.MultiplyVector(n[i]).normalized).ToArray();if(t.Length==p.Length)mesh.tangents=used.Select(i=>{var v=matrix.MultiplyVector(new Vector3(t[i].x,t[i].y,t[i].z)).normalized;return new Vector4(v.x,v.y,v.z,t[i].w*(matrix.determinant<0?-1:1));}).ToArray();if(uv.Length==p.Length)mesh.uv=used.Select(i=>uv[i]).ToArray();if(uv2.Length==p.Length)mesh.uv2=used.Select(i=>uv2[i]).ToArray();if(colors.Length==p.Length)mesh.colors=used.Select(i=>colors[i]).ToArray();mesh.triangles=original.Select(i=>remap[i]).ToArray();if(n.Length!=p.Length)mesh.RecalculateNormals();mesh.RecalculateBounds();mesh=Save(mesh,"Mesh"+(serial++)+".asset");
  var go=new GameObject(name);go.transform.SetParent(root,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=go.AddComponent<MeshRenderer>();renderer.sharedMaterial=material;renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.receiveShadows=false;return renderer;
 }
 static Mesh Quad(Vector3 a,Vector3 b,Vector3 c,Vector3 d){var mesh=new Mesh();mesh.vertices=new[]{a,b,c,d};mesh.uv=new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up};mesh.triangles=new[]{0,2,1,0,3,2};mesh.RecalculateNormals();mesh.RecalculateBounds();return mesh;}
 static void ExtendFloor(Transform root,float depth,Color color,float floor=-.1490625f){
  var mat=Material("Universal Render Pipeline/Unlit","Floor extension");mat.SetColor("_BaseColor",color);
  foreach(int side in new[]{-1,1}){float a=side<0?-4:.265f,b=side<0?-.265f:4;var mesh=Quad(new Vector3(a,floor,0),new Vector3(b,floor,0),new Vector3(b,floor,depth),new Vector3(a,floor,depth));Mesh(root,mesh,Matrix4x4.identity,mat,"Floor extension "+side);UnityEngine.Object.DestroyImmediate(mesh);}
 }
 static void Model(Transform root,string name,Material material,float scale,float heightOffset){
  string path=Base+"/Source/"+scene+"/"+name+".fbx";var importer=AssetImporter.GetAtPath(path) as ModelImporter;if(!importer)throw new InvalidDataException("scene-model-missing:"+path);importer.isReadable=true;if(scene=="RainyCafe")importer.importTangents=ModelImporterTangents.CalculateMikk;importer.materialImportMode=ModelImporterMaterialImportMode.None;importer.importCameras=false;importer.importLights=false;importer.SaveAndReimport();
  var source=AssetDatabase.LoadAssetAtPath<GameObject>(path);var instance=UnityEngine.Object.Instantiate(source);instance.transform.position=new Vector3(0,heightOffset,0);instance.transform.rotation=Quaternion.Euler(0,180,0)*instance.transform.rotation;instance.transform.localScale*=scale;
  foreach(var filter in instance.GetComponentsInChildren<MeshFilter>())for(int sub=0;sub<filter.sharedMesh.subMeshCount;sub++)Mesh(root,filter.sharedMesh,filter.transform.localToWorldMatrix,material,name+" "+filter.name,sub);
  UnityEngine.Object.DestroyImmediate(instance);
 }
 static void Train(Transform root){
  const float w=4.266666667f,h=2.4f,scale=.53f/w;var colors=new Dictionary<string,int>{{"Architecture",1024},{"Furnishings",1024},{"Lamps",512}};
  foreach(var entry in colors){var material=Material("Universal Render Pipeline/Unlit",entry.Key);material.SetTexture("_BaseMap",Texture(entry.Key+".png",entry.Value));material.SetColor("_BaseColor",Color.white);Model(root,entry.Key,material,scale,-h/2*scale);}
  for(int i=0;i<6;i++){
   var mat=Material("TrainSdk/WinterJourney"+i,"Window"+i);mat.SetFloat("_Layer",i);mat.SetTexture("_Panorama",Texture("SnowyPark.png",1024));var trees=Texture("SnowTrees.png",512);trees.wrapMode=TextureWrapMode.Clamp;mat.SetTexture("_Trees",trees);
   float z=new[]{5.8f,5.45f,5.05f,4.7f,4.5f,4.242f}[i],x=i==5?1.035f:w/2,y0=i==5?.755f:0,y1=i==5?1.965f:h;
   var mesh=Quad(new Vector3(-x,y0-h/2,z)*scale,new Vector3(x,y0-h/2,z)*scale,new Vector3(x,y1-h/2,z)*scale,new Vector3(-x,y1-h/2,z)*scale);Mesh(root,mesh,Matrix4x4.identity,mat,"WindowLayer_"+i);UnityEngine.Object.DestroyImmediate(mesh);
  }
  ExtendFloor(root,1.2f,new Color(.02f,.018f,.012f));
 }
 public static SceneDefinition Create(string selected){
  scene=selected;serial=0;folder=Base+"/Generated/"+scene;Directory.CreateDirectory(folder);AssetDatabase.Refresh();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);PlayerSettings.colorSpace=ColorSpace.Linear;TrustedRenderProfileBuilder.Install(folder);
  var root=new GameObject(scene+" SDK");var definition=root.AddComponent<SceneDefinition>();definition.templateId=new Dictionary<string,string>{{"Train","1278607b-5d1d-4b48-b156-0e53301ddf8b"},{"Showcase","3bda8a11-1641-41b9-81da-fab68e0e9bc7"},{"Parking","604e0484-64f8-4755-8668-dcfc02f0be74"},{"RainyCafe","b8499eab-d5b3-41ea-afec-fc97743e6dd8"}}[scene];definition.displayName=scene+" · SDK";definition.contentRoot=root.transform;definition.authorFrame=new Vector3(.53f,scene=="Showcase"?.3f:.298125f,scene=="Train"?.7453125f:scene=="Parking"?15.9f:scene=="RainyCafe"?3.5f:.6f);definition.reshare=false;definition.licenseName="Original local "+scene+"; licensed music sources accompany author project";definition.licenseSource="User local scene assets; public redistribution unverified";definition.licenseAttribution="Original scene creators and music authors in Audio/LICENSE.txt";
  var settings=root.AddComponent<ScenePresentationSettings>();settings.customBackground=true;settings.backgroundColor=scene=="Train"?new Color(.035f,.025f,.018f):Color.black;settings.applyInPlay=true;settings.postProcessing=false;
  root.AddComponent<WallpaperSound>().music=Music();if(scene=="Train")Train(root.transform);else if(scene=="Showcase")Showcase(root.transform);else if(scene=="Parking")Parking(root.transform);else if(scene=="RainyCafe")RainyCafe(root.transform);else throw new InvalidOperationException("scene-migration-not-implemented:"+scene);
  var camera=new GameObject("Author fixed window").AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=settings.backgroundColor;camera.gameObject.AddComponent<UniversalAdditionalCameraData>().renderPostProcessing=false;var projection=camera.gameObject.AddComponent<WindowProjection>();projection.displayWidth=definition.authorFrame.y*16/9;projection.displayHeight=definition.authorFrame.y;projection.contentDepth=definition.authorFrame.z*2;projection.SetEye(new Vector3(0,0,-.6f));RenderSettings.skybox=null;
  EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),folder+"/"+scene+"Sdk.unity");AssetDatabase.SaveAssets();return definition;
 }
 public static void Build(){string output=Environment.GetEnvironmentVariable("SDK_SCENE_OUTPUT"),selected=Environment.GetEnvironmentVariable("SDK_SCENE");try{var definition=Create(selected);var meshes=definition.GetComponentsInChildren<MeshFilter>();File.WriteAllText(Path.Combine(output,"result.json"),new JObject{{"scene",selected},{"meshes",meshes.Length},{"vertices",meshes.Sum(m=>m.sharedMesh.vertexCount)},{"scope","isolated SDK author scene creation; preview/export still required"}}.ToString());EditorApplication.Exit(0);}catch(Exception error){File.WriteAllText(Path.Combine(output,"error.txt"),error.ToString());Debug.LogException(error);EditorApplication.Exit(1);}}
}
